use split_decls_genesis :: ourprelude :: * ; use crate :: support :: { CastFrom , CastInto , Float , IntTy , MinInt } ; #[doc = " Scale the exponent."] #[doc = ""] #[doc = " From N3220:"] #[doc = ""] #[doc = " > The scalbn and scalbln functions compute `x * b^n`, where `b = FLT_RADIX` if the return type"] #[doc = " > of the function is a standard floating type, or `b = 10` if the return type of the function"] #[doc = " > is a decimal floating type. A range error occurs for some finite x, depending on n."] #[doc = " >"] #[doc = " > [...]"] #[doc = " >"] #[doc = " > * `scalbn(±0, n)` returns `±0`."] #[doc = " > * `scalbn(x, 0)` returns `x`."] #[doc = " > * `scalbn(±∞, n)` returns `±∞`."] #[doc = " >"] #[doc = " > If the calculation does not overflow or underflow, the returned value is exact and"] #[doc = " > independent of the current rounding direction mode."] #[inline] pub fn scalbn < F : Float > (mut x : F , mut n : i32) -> F where u32 : CastInto < F :: Int > , F :: Int : CastFrom < i32 > , F :: Int : CastFrom < u32 > , { let zero = IntTy :: < F > :: ZERO ; let sig_total_bits = F :: SIG_BITS + 1 ; let exp_max = F :: EXP_MAX ; let exp_min = F :: EXP_MIN ; let f_exp_max = F :: from_parts (false , F :: EXP_BIAS << 1 , zero) ; let f_exp_min = F :: from_parts (false , 1 , zero) ; let f_pow_subnorm = F :: from_parts (false , sig_total_bits + F :: EXP_BIAS , zero) ; if n > exp_max { debug_assert ! (- exp_min + F :: SIG_BITS as i32 + exp_max <= exp_max * 3) ; x *= f_exp_max ; n -= exp_max ; if n > exp_max { x *= f_exp_max ; n -= exp_max ; if n > exp_max { n = exp_max ; } } } else if n < exp_min { if F :: BITS > 16 { let mul = f_exp_min * f_pow_subnorm ; let add = - exp_min - sig_total_bits as i32 ; debug_assert ! (- exp_min + F :: SIG_BITS as i32 + exp_max <= add * 2 + - exp_min) ; x *= mul ; n += add ; if n < exp_min { x *= mul ; n += add ; if n < exp_min { n = exp_min ; } } } else { let add = - (n + sig_total_bits as i32) . clamp (exp_min , sig_total_bits as i32) ; let mul = F :: from_parts (false , (F :: EXP_BIAS as i32 - add) as u32 , zero) ; x *= mul ; n += add ; if n < exp_min { let add = - (n + sig_total_bits as i32) . clamp (exp_min , sig_total_bits as i32) ; let mul = F :: from_parts (false , (F :: EXP_BIAS as i32 - add) as u32 , zero) ; x *= mul ; n += add ; if n < exp_min { n = exp_min ; } } } } let scale = F :: from_parts (false , (F :: EXP_BIAS as i32 + n) as u32 , zero) ; x * scale }